import test from 'node:test';import assert from 'node:assert/strict';
import {journeyWeave,applyJourneyKit,writeJourneyProfile,readJourneyProfiles,joinJourney,profileSummary,normalizeJourney,rerollJourney,validJourneyValue} from '../journey-roster.js';
import {defaultHero} from '../mako.js';
const state=()=>({schema:'ash-aether.engine2/1',chapter:3,mode:'field',party:[0,2,1],recruited:[0,2,1],heroes:Array.from({length:7},(_,id)=>defaultHero(id)),items:{tonic:2},cores:['earth'],supports:['focus'],gold:40,story:{slots:1,journal:[]},frontiers:{claimed:['commission-0']}});
const profile=(id,past=false)=>{const s=state();s.party=[id];s.recruited=[id];s.journey=journeyWeave(id,7);s.chronicle={phase:past?'past':'present',hero:id,step:2};return {hero:id,savedAt:1,value:{schema:'ash-aether.enhanced-save/1',world:s}};};
test('eighteen distinct starting weaves per hero have reproducible item discipline and threads',()=>{for(let id=0;id<7;id++){const pairs=new Set();for(let seed=0;seed<18;seed++){const a=journeyWeave(id,seed);assert.deepEqual(a,journeyWeave(id,seed));pairs.add(a.approach+':'+a.thread);const s=state();applyJourneyKit(s,a);assert.equal(s.journey.hero,id);assert.equal(s.heroes[id].battleApproach,a.approach);assert.ok(Object.values(s.items).every(Number.isInteger));}assert.equal(pairs.size,18);}});
test('seven journey slots remain separate and identify the protagonist after party reordering',()=>{const data=new Map(),storage={getItem:k=>data.get(k)||null,setItem:(k,v)=>data.set(k,v)};for(let id=0;id<7;id++){const p=profile(id);p.value.world.party=[(id+1)%7,id];assert.equal(writeJourneyProfile(storage,p.value,123+id),true);}const profiles=readJourneyProfiles(storage);assert.equal(profiles.filter(Boolean).length,7);for(let id=0;id<7;id++){assert.equal(profiles[id].hero,id);assert.equal(profiles[id].savedAt,123+id);}});
test('drop-in preserves leader, campaign flags, currency and commissions and caps active party at three',()=>{const s=state(),p=profile(6),before=JSON.stringify(p),result=joinJourney(s,p);assert.deepEqual(s.party,[0,2,6]);assert.equal(result.reserved,1);assert.equal(s.gold,40);assert.equal(s.chapter,3);assert.deepEqual(s.frontiers.claimed,['commission-0']);assert.equal(JSON.stringify(p),before);assert.equal(s.heroes[6].battleApproach,p.value.world.journey.approach);assert.equal(joinJourney(s,p).joined,false);assert.equal(s.party.length,3);});
test('unfinished beginnings and active encounters cannot drop into another timeline',()=>{assert.equal(profileSummary(profile(1,true)).ready,false);assert.throws(()=>joinJourney(state(),profile(1,true)),/Finish/);const s=state();s.chronicle={phase:'past'};assert.throws(()=>joinJourney(s,profile(6)),/shared road/);const p=profile(6);p.value.battle={};assert.throws(()=>joinJourney(state(),p),/Finish/);});
test('each chosen protagonist carries actual origin progress through convergence without a second starting kit',async()=>{
 const {flow}=await import('./opening-flow.mjs');const {ORIGINS}=await import('../origin-content.js?v=5.6.0');const {convergeOrigin}=await import('../origins.js?v=5.6.0');
 for(const o of ORIGINS){const h=flow(),w=h.w,j=journeyWeave(o.hero,7);w.newGame({originId:o.id,legacy:{journey:j}});h.finish();w.state.chronicle.step=4;w.state.chronicle.choices={repair:1,approach:'battle',destiny:0};w.state.xp=25;w.state.gold=20;w.state.items.ether=0;w.state.heroes[o.hero].battleApproach=j.approach;const before=JSON.stringify(w.state.items);convergeOrigin(w);h.finish();assert.equal(w.state.party[0],o.hero);assert.equal(w.state.journey.hero,o.hero);assert.equal(w.state.heroes[o.hero].battleApproach,j.approach);assert.equal(w.state.xp,25);assert.equal(w.state.gold,20);assert.equal(JSON.stringify(w.state.items),before);const save=w.save();w.restore(save);assert.equal(w.state.party[0],o.hero);}
});

test('manual starting choices are normalized without changing the selected protagonist',()=>{const j=normalizeJourney(2,{hero:6,seed:Infinity,approach:'witness',thread:'echo'});assert.equal(j.hero,2);assert.equal(j.approach,'witness');assert.equal(j.thread,'echo');assert.equal(j.seed,0);const safe=normalizeJourney(2,{approach:'missing',thread:'missing'});assert.ok(safe.approach);assert.ok(safe.thread);assert.doesNotThrow(()=>journeyWeave(2,Infinity));});
test('reroll changes a manually edited weave even if the next seed describes the same combination',()=>{const current={...journeyWeave(0,0),approach:'saboteur',thread:'shelter'};const next=rerollJourney(0,current,()=>0);assert.notEqual(next.approach+':'+next.thread,current.approach+':'+current.thread);});
test('incomplete or mismatched character profiles are excluded instead of crashing the roster',()=>{const p=profile(1);p.hero=6;assert.equal(profileSummary(p),null);const data=new Map([[ 'ash-aether-journey-hero-6',JSON.stringify(p)]]),storage={getItem:k=>data.get(k)||null};assert.equal(readJourneyProfiles(storage)[6],null);assert.equal(validJourneyValue({schema:'ash-aether.enhanced-save/1',world:{schema:'ash-aether.engine2/1'}}),false);});
test('a full profile storage partition does not interrupt the current journey',()=>{assert.equal(writeJourneyProfile({setItem(){throw Error('Quota exceeded');}},profile(1).value),false);});
test('a newly joining traveller matches the current crew level without importing another save’s levels',()=>{const s=state();s.heroes[0]=defaultHero(0,12);const p=profile(6);p.value.world.heroes[6]=defaultHero(6,45);joinJourney(s,p);assert.equal(s.heroes[6].level,12);assert.equal(s.heroes[6].maxHp,defaultHero(6,12).maxHp);assert.equal(s.heroes[6].hp,s.heroes[6].maxHp);});
test('a dialogue or other unresolved mode cannot accept a drop-in',()=>{const s=state();s.mode='dialog';assert.throws(()=>joinJourney(s,profile(6)),/shared road/);const p=profile(1);p.value.world.mode='dialog';assert.equal(profileSummary(p).ready,false);});
